import numpy as npfrom mirrors import MirrorPrismclass RectangularPrism(MirrorPrism):    def __init__(self, ):        self._aspect = (1. + np.sqrt(5.)) / 2.        super(RectangularPrism, self).__init__()    @classmethod    def get_name(cls):        return "rectangle"    def get_rel_shape(self, margin=0.05):        """        Get coordinates of vertices of current shape, best fit into the unit square.        leave "margin" around border.        """        if self._aspect > 1:            y_span = (0.5 - margin / 2.) / self._aspect            x_span = 0.5 - margin / 2.        else:            x_span = (0.5 - margin / 2.) * self._aspect            y_span = 0.5 - margin / 2.        points = np.array([[0.5 - x_span, 0.5 - y_span],                           [0.5 + x_span, 0.5 - y_span],                           [0.5 + x_span, 0.5 + y_span],                           [0.5 - x_span, 0.5 + y_span], ])        return points    def _mouse_adjust(self, pos, d_pos, d_button, button_state):        if button_state[0] == 1:            if d_pos is not None:                change = d_pos[1]                if change != 0:                    self._aspect *= (1.05 ** np.sign(change))                    self._mask = None    @classmethod    def get_icon_vertices(cls):        top_y = super().ICON_LAYOUT['fig_top_y']        bottom_y = super().ICON_LAYOUT['fig_bottom_y']        text_y = super().ICON_LAYOUT['text_bottom_y']        area_height = bottom_y - top_y        center_y = (top_y + bottom_y) / 2        rect_height = area_height / 2        rect_width = 0.75        return {'points': [(0.5 + rect_width / 2, center_y + rect_height / 2),                           (0.5 - rect_width / 2, center_y + rect_height / 2),                           (0.5 - rect_width / 2, center_y - rect_height / 2),                           (0.5 + rect_width / 2, center_y - rect_height / 2),                           (0.5 + rect_width / 2, center_y - rect_height / 3),                           (0.5 + rect_width / 2, center_y)],                'text_center_bottom': [0.5, text_y]}